import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Enzi ya Uchunguzi wa Kati ya Ndege","description":"","frontmatter":{},"headers":[],"relativePath":"sw/78-跨位面探索纪元.md","filePath":"sw/78-跨位面探索纪元.md","lastUpdated":1789183869000}'),e={name:"sw/78-跨位面探索纪元.md"};function o(k,a,h,l,w,g){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="enzi-ya-uchunguzi-wa-kati-ya-ndege" tabindex="-1">Enzi ya Uchunguzi wa Kati ya Ndege <a class="header-anchor" href="#enzi-ya-uchunguzi-wa-kati-ya-ndege" aria-label="Permalink to &quot;Enzi ya Uchunguzi wa Kati ya Ndege&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>78</td></tr><tr><td>Moduli</td><td>Enzi za Kihistoria na Matukio Muhimu</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Uchunguzi wa kati ya ndege, ugunduzi mkubwa wa ndege, makubaliano ya kichunguzi, tazama kwanza kisha uingilie, ushirikiano wa kati ya nyota</td></tr></tbody></table><h2 id="_1-masharti-ya-ufunguo-wa-enzi-ya-uchunguzi-wa-kati-ya-ndege" tabindex="-1">1. Masharti ya Ufunguo wa Enzi ya Uchunguzi wa Kati ya Ndege <a class="header-anchor" href="#_1-masharti-ya-ufunguo-wa-enzi-ya-uchunguzi-wa-kati-ya-ndege" aria-label="Permalink to &quot;1. Masharti ya Ufunguo wa Enzi ya Uchunguzi wa Kati ya Ndege&quot;">​</a></h2><p>Enzi ya Uchunguzi wa Kati ya Ndege ni enzi mpya iliyoanzishwa baada ya kuanzishwa kwa Jamhuri ya Makabila Yote, inayolingana na hatua ya mpito kutoka &quot;mageuzi ya fahari&quot; hadi &quot;ushirikiano wa kati ya nyota&quot; katika njia ya kuinua ya hatua nne. Ufunguo wa enzi hii unahitaji ukomavu wa pamoja wa masharti matatu:</p><ul><li><strong>Masharti ya teknolojia</strong>: Teknolojia ya sheria ya nafasi inafikia hali ya &quot;chanzo cha nafasi&quot;, ufunguo wa thabiti wa njia ya kati ya ndege unakuwa inawezekana; teknolojia ya kioo cha nakala na nafasi iliyotengwa imekomaa, inatoa hakikisho la teknolojia kwa uchunguzi wa uchafuzi mdogo</li><li><strong>Masharti ya mfumo</strong>: Jamhuri ya Makabila Yote imeanzishwa, sera ya umoja ya uchunguzi wa kati ya ndege na makubaliano ya kichunguzi yamekamilika</li><li><strong>Masharti ya motisha</strong>: Kazi ya kuinua ya ndege zinazojulikana inaendelea kwa utaratibu, ustaarabu una uwezo na nia ya kupanua kwenda kwenye ndege zisizojulikana</li></ul><p>Wakati masharti haya matatu yanakomaa pamoja, Jamhuri ya Makabila Yote inatangaza rasmi kuanzisha &quot;Mpango wa Uchunguzi Mkubwa&quot;, na Enzi ya Uchunguzi wa Kati ya Ndege inaanzishwa kwa njia hii.</p><h2 id="_2-kanuni-za-msingi-za-uchunguzi-wa-kati-ya-ndege" tabindex="-1">2. Kanuni za Msingi za Uchunguzi wa Kati ya Ndege <a class="header-anchor" href="#_2-kanuni-za-msingi-za-uchunguzi-wa-kati-ya-ndege" aria-label="Permalink to &quot;2. Kanuni za Msingi za Uchunguzi wa Kati ya Ndege&quot;">​</a></h2><p>Uchunguzi wa kati ya ndege unafuata kabisa kanuni zifuatazo za msingi, kanuni hizi zimeandikwa katika &quot;Kanuni ya Msingi ya Uchunguzi wa Kati ya Ndege&quot;:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maana</th></tr></thead><tbody><tr><td>Tazama kwanza kisha uingilie kwa ukomo</td><td>Kwa ndege zisizojulikana, kwanza fanya uchunguzi wa passiv, baada ya uelewa wa kutosha tu fanya mawasiliano na uingiliaji wa ukomo</td></tr><tr><td>Uchunguzi wa uchafuzi mdogo</td><td>Tumia mpango wa kichunguzi wa kioo cha nakala + nafasi iliyotengwa, tupe tu maarifa nyuma, usilete vitu na uhai ndani au nje</td></tr><tr><td>Uhifadhi wa ustaarabu wa asili</td><td>Kwa ndege zenye ustaarabu wa asili, heshima haki zao za maendeleo ya kujitegemea, usilazimishe mfumo wa ushirikiano</td></tr><tr><td>Kushirikiwa wa rasilimali</td><td>Maarifa na rasilimali zilizogunduliwa katika uchunguzi ni za ushirikiano wa ustaarabu wote, shirika lolote lisiweze kudhibiti matokeo ya uchunguzi</td></tr><tr><td>Usalama wa kwanza</td><td>Usalama katika mchakato wa uchunguzi daima huwekwa katika nafasi ya kwanza, uchunguzi wa ndege zenye hatari kubwa lazima kupitia tathmini ya hatari ya kina</td></tr></tbody></table><h2 id="_3-njia-za-teknolojia-za-uchunguzi" tabindex="-1">3. Njia za Teknolojia za Uchunguzi <a class="header-anchor" href="#_3-njia-za-teknolojia-za-uchunguzi" aria-label="Permalink to &quot;3. Njia za Teknolojia za Uchunguzi&quot;">​</a></h2><p>Uchunguzi wa kati ya ndege unatumia kwa umoja teknolojia kadhaa za msingi za ustaarabu wa ushirikiano:</p><ol><li><strong>Teknolojia ya skana ya ndege</strong>: Skana ya ndege ya mbali kulingana na moduli ya uelewa wa sheria ya nafasi, inaweza kupata taarifa za msingi (muundo wa nafasi, kiwango cha nishati, dalili za uhai, n.k.) bila kuwasiliana na ndege ya lengo</li><li><strong>Mpango wa kichunguzi wa kioo cha nakala</strong>: Fanya nakala ya kioo cha usahihi wa juu ya ndege ya lengo, fanya utafiti wa kina kwenye nakala ya kioo ndani ya nafasi iliyotengwa, tupe tu maarifa nyuma</li><li><strong>Uchunguzi wa mawasiliano wa kati ya ndege</strong>: Kifaa cha mawasiliano cha sheria cha ndogo, kinaweza kutumwa kwenye ndege ya lengo kwa ajili ya uchunguzi wa karibu, data hupatikana kwa wakati halisi kupitia mtandao wa mawasiliano wa kati ya ndege</li><li><strong>Uelewa wa eneo la fahari</strong>: Wafundishaji wa kiwango cha juu wanafanya uelewa wa mbali wa ndege ya lengo kupitia eneo la fahari, wanapata taarifa za kiwango cha fahari ambazo teknolojia ya skana haiwezi kushika</li><li><strong>Uwekaji wa nanga wa mbali</strong>: Kwa ndege zenye kiwango cha juu cha usalama, inawezekana kuweka nanga ya muda kwa mbali, kujenga njia ya muunganisho thabiti</li></ol><h2 id="_4-ushirikiano-na-utekelezaji-wa-uchunguzi" tabindex="-1">4. Ushirikiano na Utekelezaji wa Uchunguzi <a class="header-anchor" href="#_4-ushirikiano-na-utekelezaji-wa-uchunguzi" aria-label="Permalink to &quot;4. Ushirikiano na Utekelezaji wa Uchunguzi&quot;">​</a></h2><p>Uchunguzi wa kati ya ndege unashirikishwa na kutekelezwa kwa umoja na &quot;Ofisi ya Uchunguzi wa Kati ya Ndege&quot; ya Jamhuri ya Makabila Yote, na inatumia muundo wa &quot;uchunguzi wa daraja&quot;:</p><table tabindex="0"><thead><tr><th>Daraja la Uchunguzi</th><th>Aina ya Lengo</th><th>Njia ya Uchunguzi</th><th>Uandaaaji wa Watu</th></tr></thead><tbody><tr><td>Uchunguzi wa Daraja la 1</td><td>Ndege za kavu zisizo na uhai</td><td>Skana ya mbali + utafiti wa kioo cha nakala</td><td>Kimsingi timu ya teknolojia</td></tr><tr><td>Uchunguzi wa Daraja la 2</td><td>Ndege zenye uhai wa chini</td><td>Kichunguzi cha kioo cha nakala + uchunguzi mdogo wa eneo</td><td>Timu ya teknolojia + wanabiolojia</td></tr><tr><td>Uchunguzi wa Daraja la 3</td><td>Ndege zenye ustaarabu wa asili</td><td>Tazama kwanza kisha uingilie, fuata kabisa itifaki ya mawasiliano</td><td>Timu kamili + madiploma + watazamaji wa maadili</td></tr><tr><td>Uchunguzi wa Daraja la 4</td><td>Ndege zenye hatari kubwa / zisizojulikana</td><td>Utafiti wa kuiga ndani ya nafasi iliyotengwa tu, mawasiliano ya eneo yamepigwa marufuku</td><td>Timu ya usalama ya kiwango cha juu zaidi</td></tr></tbody></table><p>Kila mradi wa uchunguzi lazima kupitia mchakato kamili wa &quot;ombi la uchunguzi — tathmini ya hatari — ukaguzi wa maadili — idhini na utekelezaji — ufuatiliaji wa mchakato — kushirikiwa wa matokeo&quot;.</p><h2 id="_5-ugunduzi-muhimu-wa-enzi-ya-uchunguzi" tabindex="-1">5. Ugunduzi Muhimu wa Enzi ya Uchunguzi <a class="header-anchor" href="#_5-ugunduzi-muhimu-wa-enzi-ya-uchunguzi" aria-label="Permalink to &quot;5. Ugunduzi Muhimu wa Enzi ya Uchunguzi&quot;">​</a></h2><p>Baada ya kuanzishwa kwa Enzi ya Uchunguzi wa Kati ya Ndege, ustaarabu wa ushirikiano umefanya ugunduzi wa mfululizo wa muhimu:</p><ul><li><strong>Ugunduzi wa makabila mapya</strong>: Kugunduliwa kwa idadi kubwa ya makabila ya akili ambayo haijawahi kujulikana katika ndege zisizojulikana, ukoo wa makabila yote umepanuliwa kwa kiwango kikubwa. Makabila haya mapya baada ya chaguo la hiari wanajiunga polepole na Jamhuri ya Makabila Yote</li><li><strong>Ugunduzi wa sheria mpya</strong>: Kuna tofauti katika muundo wa sheria za ndege tofauti, na toleo la sheria mpya kadhaa limegunduliwa katika uchunguzi, likiimarisha msingi wa nadharia ya mifumo ya miungu mia tatu</li><li><strong>Mabaki ya ustaarabu wa kale</strong>: Kugunduliwa kwa mabaki ya ustaarabu kadhaa uliopotea kutoka enzi ya kabla ya nanga, kupata maarifa mengi ya kihistoria ya thamani kupitia kichunguzi cha kioo cha nakala</li><li><strong>Ustaarabu wa ushirikiano wa ndege nyingine</strong>: Kugunduliwa katika baadhi ya ndege kwa ustaarabu wa asili ambao ulitengeneza dhana ya ushirikiano kwa kujitegemea, na kuunda uwiano wa mawazo kupitia nafasi na ustaarabu wa ushirikiano wa nanga</li><li><strong>Uchunguzi wa mipaka ya ulimwengu</strong>: Uchunguzi unakagua polepole mipaka inayojulikana ya Hengyuanzhou, uelewa wa muundo wa jumla wa ulimwengu unaendelea kina</li></ul><h2 id="_6-changamoto-na-tafakari-katika-uchunguzi" tabindex="-1">6. Changamoto na Tafakari katika Uchunguzi <a class="header-anchor" href="#_6-changamoto-na-tafakari-katika-uchunguzi" aria-label="Permalink to &quot;6. Changamoto na Tafakari katika Uchunguzi&quot;">​</a></h2><p>Uchunguzi wa kati ya ndege haukuwa wa kila wakati kwa urahisi, na katika mchakato pia walikabiliwa na changamoto:</p><ul><li><strong>Mgongano wa utamaduni</strong>: Katika mawasiliano na ustaarabu wa asili, kulikuwa na makosa ya utambuzi wa utamaduni na mgongano, ambayo ilisukuma kuimarishwa kwa kuendelea kwa itifaki ya mawasiliano</li><li><strong>Mjadala wa maadili wa uchunguzi</strong>: Kulikuwa na mjadala wa kuendelea wa maadili kuhusu &quot;je, tunapaswa kuwasiliana kwa hiari na ustaarabu wa asili&quot;, na mwishowe kulikuwa na makubaliano ya &quot;kutoa hiari, kuepuka, heshima chaguo&quot;</li><li><strong>Ajali ya usalama</strong>: Kufanyika kwa ajali ya kuvunjika kwa kizuizi cha nafasi iliyotengwa katika uchunguzi wa ndege zenye hatari kubwa; ingawa haikusababisha matokeo makubwa, lakini ilisukuma kuimarishwa zaidi kwa viwango vya usalama</li><li><strong>Usambazaji wa rasilimali</strong>: Uchunguzi wa kiwango kikubwa unahitaji matumizi ya rasilimali nyingi, usawa kati ya uwekezaji wa uchunguzi na uwekezaji wa maisha ya watu wa ndani umekuwa kiini cha mjadala wa kisiasa</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Enzi ya Uchunguzi wa Kati ya Ndege ni &quot;Enzi ya Uvuvuzaji Mkubwa&quot; ya ustaarabu wa ushirikiano wa nanga. Imepanua mtazamo wa ustaarabu kutoka ndege zinazojulikana kwenda ulimwengu wote, na wakati wa kugundua dunia mpya pia imeimarisha uelewa wa kujitegemea. Mpango wa uchunguzi wa uchafuzi mdogo wa kioo cha nakala + nafasi iliyotengwa, unafanya uchunguzi wa ustaarabu wa ushirikiano uwe tofauti na upanuzi wowote wa ukoloni wa kuchambua katika historia — kile tunachokileta sio ushindi na uchambaji, bali heshima na maarifa; kile tunachorudisha sio rasilimali na watumwa, bali uelewa na hekima. Wakati ndege zilizochunguzwa ziwe nyingi zaidi, na mtandao wa nanga uwe mnene zaidi, mlango wa enzi ya ushirikiano wa kati ya nyota utafunguliwa polepole.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>77-Uanzishaji wa Jamhuri ya Makabila Yote</li><li>79-Tarajio la Enzi ya Ushirikiano wa Kati ya Nyota</li><li>84-Mpango wa Jumla wa Makubaliano ya Kichunguzi</li></ul>',26)])])}const r=i(e,[["render",o]]);export{s as __pageData,r as default};
